import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
} from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { presentContactDetail } from '../../../interfaces/presentsetup';
import { ActivatedRoute } from '@angular/router';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import { ContactFormComponent } from '../../../../shared/components/contacts/contact-form/contact-form.component';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { LocationStrategy } from '@angular/common';
import { HeaderService } from '../../../../core/services/header/header.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-create-schedule',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonComponent, ContactFormComponent, AvatarComponent],
  templateUrl: './create-schedule.component.html',
  styleUrl: './create-schedule.component.scss',
})
export class CreateScheduleComponent {
  witnessList: presentContactDetail[] = [];
  nCaseid: string;

  isNew: boolean = false;

  nContactid: string;
  nPresentid: number | null = null;
  nPCid: number | null = null;

  constructor(
    private PSservice: PresentsetupService,
    private cm: CommonfunctionService,
    private route: ActivatedRoute,
    private cdr: ChangeDetectorRef,
    private location: LocationStrategy,
    private hs: HeaderService,
    private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;

    params = JSON.parse(decodeURIComponent(params['id']));

    this.nCaseid = params && params['id'] ? params['id'] : null;
    hs.nCaseid = this.nCaseid;

    this.nContactid = params && params['nCid'] ? params['nCid'] : null;

    this.nPresentid = params['nPid'] || null;
    this.nPCid = params['nPCid'] || null;

    // disable window history
    history.pushState(null, null, window.location.href);
    this.location.onPopState(() => {
      history.pushState(null, null, window.location.href);
    });

    userPermissions.userPermissionList(this.nCaseid);

  }

  ngOnInit() {
    this.getContactlist();
    // this.cdr.detectChanges();
  }

  async getContactlist() {
    this.witnessList = await this.PSservice.getcontactList(this.nCaseid, 'W');
    if (this.witnessList.length == 0) {
      this.isNew = true;
    }
    this.cdr.detectChanges();
  }

  outputEvent(event: any) {
    if (event.event == 'NEW_ADDED') {
      this.isNew = false;
      this.getContactlist();
    }
    if (event.event == 'CLOSE') {
      this.isNew = false;
    }
  }

  gotoFile() {
    if (!this.nContactid || !this.nCaseid) return;

    let data = {
      id: this.nCaseid,
      cid: this.nContactid,
    };
    if (this.nPresentid) {
      data['nPid'] = this.nPresentid;
    }
    if (this.nPCid) {
      data['nPCid'] = this.nPCid;
    }
    this.cm.gotoUrl('/present/choose-docs', data);
  }
}
